/*自动隐藏文字*/
.header {
  flex: none;
  padding: 15px;
  text-align: center;
}
.header h2 {
  color: var(--color-font);
  word-break: break-all;
}
.main {
  padding: 0 15px;
  width: 360px;
  display: flex;
  flex-flow: column nowrap;
  min-height: 0;
}
.title {
  font-size: 14px;
  color: var(--color-font-label);
  padding: 10px 0 8px;
}
.list {
  display: flex;
  flex-flow: row wrap;
  font-size: 14px;
}
.listItem {
  width: 50%;
  padding-left: 10px;
  margin-bottom: 8px;
  box-sizing: border-box;
}
.footer {
  margin: 20px 0 15px auto;
}
.btn {
  min-width: 70px;
}
.btn + .btn {
  margin-left: 10px;
}
