/*自动隐藏文字*/
.main {
  padding: 15px;
  max-width: 530px;
  min-width: 280px;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  min-height: 0;
}
.main h2 {
  font-size: 16px;
  color: var(--color-font);
  line-height: 1.3;
  text-align: center;
}
.content {
  padding-top: 15px;
  font-size: 14px;
}
.row {
  padding-top: 5px;
}
.inputGroup {
  display: flex;
  align-items: center;
}
.input {
  flex: auto;
}
.inputLabel {
  flex: none;
  margin-left: 10px;
}
.tip {
  visibility: hidden;
}
.tip.show {
  visibility: visible;
}
.footer {
  margin-top: 20px;
  display: flex;
  flex-flow: row nowrap;
}
.footerBtn {
  flex: auto;
  height: 36px;
  line-height: 36px;
  padding: 0 10px !important;
  width: 150px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.footerBtn + .footerBtn {
  margin-left: 15px;
}
.ruleLink {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
