/*自动隐藏文字*/
.hotKeyContainer {
  display: flex;
  flex-flow: row wrap;
  margin-bottom: 15px;
  transition: opacity 0.4s ease;
}
.hotKeyItem {
  width: 30%;
  padding-right: 35px;
  margin-top: 15px;
  box-sizing: border-box;
}
.hotKeyItemTitle {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  padding-bottom: 5px;
  color: var(--color-font-label);
  font-size: 12px;
}
.hotKeyItemInput {
  width: 100%;
  box-sizing: border-box;
}
.hotKeyItemInput:focus {
  background-color: var(--color-primary-background-active);
  text-decoration: none;
}
.hotKeyItemInput::placeholder {
  color: var(--color-200) !important;
}
.hotKeyFailed {
  text-decoration: line-through;
}
