/*自动隐藏文字*/
.contnet {
  display: flex;
  flex-flow: column nowrap;
  gap: 3px;
  min-height: 0;
  flex: none;
}
.convolution {
  display: flex;
  flex-flow: column wrap;
  gap: 15px;
  width: 100%;
}
.convolutionList {
  display: flex;
  flex-flow: row wrap;
  gap: 8px;
  width: 100%;
}
.checkbox {
  margin-right: 10px;
  font-size: 12px;
}
.sliderList {
  display: flex;
  flex-flow: column nowrap;
  gap: 15px;
  width: 100%;
  transition: opacity 0.4s ease;
}
.sliderList.disabled {
  opacity: 0.4;
}
.sliderItem {
  display: flex;
  flex-flow: row nowrap;
  gap: 8px;
}
.slider {
  flex: auto;
}
.label {
  flex: none;
  font-size: 12px;
}
.value {
  flex: none;
  width: 40px;
  font-size: 12px;
  text-align: center;
}
.value.active {
  color: var(--color-primary-font);
}
.saveList {
  display: flex;
  flex-flow: row wrap;
  margin-top: 10px;
  gap: 10px;
}
