/*自动隐藏文字*/
.tagList {
  font-size: 12px;
  position: relative;
}
.tagList.active .label .icon svg {
  transform: rotate(180deg);
}
.tagList.active .list {
  opacity: 1;
  transform: scaleY(1);
}
.label {
  padding: 8px 15px;
  transition: background-color 0.4s ease;
  box-sizing: border-box;
  text-align: center;
  color: var(--color-button-font);
  cursor: pointer;
  display: flex;
}
.label span {
  flex: auto;
}
.label .icon {
  flex: none;
  margin-left: 7px;
  line-height: 0;
}
.label .icon svg {
  width: 0.9em;
  transition: transform 0.2s ease;
  transform: rotate(0);
}
.label:hover {
  background-color: var(--color-button-background-hover);
}
.label:active {
  background-color: var(--color-button-background-active);
}
.list {
  position: absolute;
  top: 100%;
  width: 645px;
  left: 0;
  border-bottom-right-radius: 5px;
  background-color: var(--color-main-background);
  opacity: 0;
  transform: scaleY(0);
  overflow-y: auto;
  transform-origin: 0 0 0;
  max-height: 250px;
  transition: 0.25s ease;
  transition-property: transform, opacity;
  z-index: 10;
  padding: 10px;
  box-sizing: border-box;
}
.list li {
  cursor: pointer;
  padding: 8px 15px;
  text-align: center;
  outline: none;
  transition: background-color 0.4s ease;
  background-color: var(--color-button-background);
  box-sizing: border-box;
}
.list li:hover {
  background-color: var(--color-button-background-hover);
}
.list li:active {
  background-color: var(--color-button-background-active);
}
.type {
  padding-top: 10px;
  padding-bottom: 3px;
  color: var(--color-font-label);
}
.tag {
  display: inline-block;
  margin: 5px;
  background-color: var(--color-button-background);
  padding: 8px 10px;
  border-radius: 5px;
  transition: background-color 0.4s ease;
  cursor: pointer;
}
.tag:hover {
  background-color: var(--color-button-background-hover);
}
.tag:active {
  background-color: var(--color-button-background-active);
}
