/*自动隐藏文字*/
.footerLeftControlBtns {
  display: flex;
  flex-flow: row nowrap;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
}
.footerLeftControlBtns button {
  width: 20px;
  color: var(--color-font);
}
.footerLeftControlBtns .footerLeftControlBtn {
  opacity: 0.5;
  cursor: pointer;
  transition: opacity 0.4s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: transparent;
  border: none;
  padding: 0;
}
.footerLeftControlBtns .footerLeftControlBtn:hover {
  opacity: 0.9;
}
.footerLeftControlBtns .footerLeftControlBtn.active {
  color: var(--color-primary);
  opacity: 0.8;
}
.footerLeftControlBtns .lrcBtn {
  width: 20px;
}
