/*自动隐藏文字*/
.leaderboard {
  height: 100%;
  display: flex;
  position: relative;
}
.header {
  flex: none;
  width: 100%;
  display: flex;
  flex-flow: row nowrap;
}
.tab {
  flex: auto;
}
.select {
  flex: none;
  width: 80px;
}
.content {
  flex: auto;
  display: flex;
  overflow: hidden;
  flex-flow: column nowrap;
}
.lists {
  flex: none;
  width: 14.8%;
  display: flex;
  flex-flow: column nowrap;
}
.listsHeader {
  position: relative;
}
.listsSelect {
  font-size: 12px;
  border-bottom: var(--color-list-header-border-bottom);
  flex: none;
}
.listsSelect:hover :global(.icon) {
  opacity: 1;
}
.listsSelect > :global(.content) {
  display: block;
  width: 100%;
}
.listsSelect :global(.label-content) {
  background-color: transparent !important;
  line-height: 38px;
  height: 38px;
  border-radius: 0;
}
.listsSelect :global(.label-content):hover {
  background: none !important;
}
.listsSelect :global(.label) {
  color: var(--color-font) !important;
}
.listsSelect :global(.icon) {
  opacity: 0.6;
  transition: opacity 0.3s ease;
}
.listsSelect :global(.selection-list) {
  max-height: 500px;
  box-shadow: 0 1px 8px 0 rgba(0, 0, 0, 0.2);
}
.listsSelect :global(.selection-list) li {
  line-height: 38px;
  font-size: 13px;
}
.listsSelect :global(.selection-list) li:hover {
  background-color: var(--color-button-background-hover);
}
.listsSelect :global(.selection-list) li:active {
  background-color: var(--color-button-background-active);
}
.list {
  position: relative;
  overflow: hidden;
  height: 100%;
  flex: auto;
  display: flex;
  flex-flow: column nowrap;
}
