/*自动隐藏文字*/
.main {
  display: flex;
  flex-flow: row nowrap;
  height: 100%;
  border-top: var(--color-list-header-border-bottom);
}
.toc {
  flex: 0 0 16%;
  overflow-y: scroll;
}
.tocH2 {
  line-height: 1.5;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 13px;
  color: var(--color-font);
  padding: 8px 10px;
  transition: 0.3s ease;
  transition-property: background-color, color;
}
.tocH2:not(.active) {
  cursor: pointer;
}
.tocH2:not(.active):hover {
  background-color: var(--color-button-background-hover);
}
.tocH2.active {
  color: var(--color-primary);
}
.activeIcon {
  height: 0.9em;
  width: 0.9em;
  margin-left: -0.45em;
  vertical-align: -0.05em;
}
.setting {
  padding: 0 15px 15px;
  font-size: 14px;
  box-sizing: border-box;
  overflow-y: auto;
  height: 100%;
  position: relative;
  width: 100%;
}
.setting :global dt {
  border-left: 5px solid var(--color-primary-alpha-700);
  padding: 3px 7px;
  margin: 15px 0;
}
.setting :global dt + dd h3 {
  margin-top: 0;
}
.setting :global dd > div {
  padding: 0 15px;
}
.setting :global h3 {
  font-size: 12px;
  margin: 25px 0 15px;
}
.setting :global .p {
  padding: 3px 0;
  line-height: 1.3;
}
.setting :global .p .btn + .btn {
  margin-left: 10px;
}
.setting :global .help-btn {
  padding: 0;
  margin: 0 0.4em;
  border: none;
  background: none;
  color: var(--color-button-font);
  cursor: pointer;
  transition: opacity 0.2s ease;
}
.setting :global .help-btn:hover {
  opacity: 0.7;
}
.setting :global .help-icon {
  margin: 0 0.4em;
}
