/*自动隐藏文字*/
.main {
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  min-height: 0;
}
.main h2 {
  font-size: 13px;
  color: var(--color-font);
  line-height: 1.3;
  text-align: center;
  padding: 15px;
}
.name {
  color: var(--color-primary);
}
.btnContent {
  flex: auto;
  max-height: 100%;
  padding-right: 15px;
  display: flex;
  flex-flow: row wrap;
  justify-content: space-evenly;
}
.btn {
  position: relative;
  box-sizing: border-box;
  margin-left: 15px;
  margin-bottom: 15px;
  height: 36px;
  line-height: 36px;
  padding: 0 10px !important;
  width: calc(33.33333333% - 15px);
  min-width: 160px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.newList {
  border: 1px dashed var(--color-primary-font-hover);
  color: var(--color-primary-font-hover);
  opacity: 0.7;
}
.newList svg {
  height: 18px;
  margin-top: 9px;
}
.newList.editing {
  opacity: 1;
}
.newList.editing svg {
  display: none;
}
.newList.editing .newListInput {
  display: block;
}
.newListInput {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 34px;
  line-height: 34px;
  background: none !important;
  font-size: 14px;
  text-align: center;
  font-family: inherit;
  box-sizing: border-box;
  padding: 0 10px;
  border-radius: 0;
  display: none;
}
@media (min-width: 1920px) {
  .btn {
    width: calc(25% - 15px);
  }
}
@media (min-width: 2560px) {
  .btn {
    width: calc(20% - 15px);
  }
}
@media (min-width: 3840px) {
  .btn {
    width: calc(16.66666667% - 15px);
  }
}
