/*自动隐藏文字*/
.listItem {
  border-bottom: 1px dashed var(--color-primary-alpha-700);
}
.content {
  padding: 12px 0;
  font-size: 13px;
  color: var(--color-font);
  display: flex;
}
.left {
  flex: none;
}
.avatar {
  width: 40px;
  border-radius: 4px;
  box-shadow: 0 0 2px rgba(0, 0, 0, 0.15);
}
.right {
  flex: auto;
  min-width: 0;
  margin-left: 10px;
}
.info {
  display: flex;
  flex-flow: row nowrap;
  gap: 15px;
  width: 100%;
  height: 40px;
  line-height: 1.3;
  color: var(--color-450);
}
.baseInfo {
  height: 100%;
  flex: auto;
  display: flex;
  min-width: 0;
  flex-flow: column nowrap;
  justify-content: space-evenly;
}
.metaInfo {
  display: flex;
  flex-flow: row nowrap;
  min-width: 0;
  gap: 10px;
  overflow: hidden;
}
.name {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--color-650);
}
.label {
  flex: none;
  font-size: 12px;
}
.likes {
  flex: none;
  font-size: 11px;
  text-align: right;
  padding-top: 3px;
  align-self: flex-start;
}
.likesIcon {
  width: 12px;
  height: 12px;
  margin-right: 3px;
  color: var(--color-primary-alpha-500);
}
.comment_text {
  text-align: justify;
  font-size: 14px;
  line-height: 1.5;
  word-break: break-all;
  overflow-wrap: break-word;
  white-space: pre-wrap;
}
.comment_images {
  display: flex;
  flex-flow: row wrap;
  gap: 5px;
  margin-top: 5px;
}
.comment_images img {
  max-width: 240px;
}
.reply_floor {
  padding: 0 0 0 15px;
  margin-left: 30px;
  border-radius: 0.5rem;
  background-color: var(--color-primary-light-500-alpha-700);
}
.reply_floor:last-child {
  margin-bottom: 12px;
}
.reply_floor .listItem:last-child {
  border-bottom: none;
}
.reply_floor .right {
  margin-right: 10px;
}
