/*自动隐藏文字*/
.list {
  display: flex;
  flex-flow: row nowrap;
  font-size: 12px;
  gap: 25px;
  padding: 0 15px;
}
.list.left {
  justify-content: flex-start;
}
.list.center {
  justify-content: center;
}
.list.right {
  justify-content: flex-end;
}
.listItem {
  display: block;
  cursor: pointer;
  transition: color 0.4s ease;
}
.listItem:hover {
  color: var(--color-primary);
}
.listItem.active {
  color: var(--color-primary);
  cursor: default;
}
.listItem.active > .label:after {
  opacity: 1;
  transform: translateY(0);
}
.label {
  display: block;
  position: relative;
  padding: 8px 0;
}
.label:after {
  display: block;
  position: absolute;
  content: '';
  left: 0;
  bottom: 0;
  width: 100%;
  height: 2px;
  border-radius: 20px;
  background-color: transparent;
  transform: translateY(-4px);
  opacity: 0;
  background-color: var(--color-primary-alpha-300);
  transition: 0.3s ease;
  transition-property: transform, opacity;
}
