/*自动隐藏文字*/
.toolbar {
  display: flex;
  height: 54px;
  align-items: center;
  justify-content: space-between;
  padding-left: 15px;
  -webkit-app-region: drag;
  z-index: 2;
}
.toolbar.fullscreen {
  -webkit-app-region: no-drag;
}
.toolbar.fullscreen .logo {
  display: none;
}
.toolbar.controlBtnLeft .control {
  display: none;
}
.toolbar.controlBtnRight {
  justify-content: space-between;
}
.logo {
  box-sizing: border-box;
  padding: 0 21.6px;
  height: 54px;
  color: var(--color-primary);
  flex: none;
  text-align: center;
  line-height: 54px;
  font-weight: bold;
}
