/*自动隐藏文字*/
.container {
  height: 100%;
  display: flex;
  flex-flow: column nowrap;
  position: relative;
}
.header {
  flex: none;
  width: 100%;
  display: flex;
  flex-flow: row nowrap;
  padding-bottom: 5px;
}
.left {
  flex: auto;
  display: flex;
  flex-flow: row nowrap;
}
.btn {
  color: var(--color-font);
  transition: color 0.3s ease;
  background: none !important;
}
.btn:hover {
  color: var(--color-primary-font-hover);
}
.select {
  font-size: 12px;
  width: auto;
  flex: none;
  padding: 0 5px;
}
.select:hover :global(.icon) {
  opacity: 1;
}
.select :global .label-content {
  background-color: transparent !important;
  transition: color 0.3s ease;
  color: var(--color-font);
  border-radius: 0;
}
.select :global .label-content:hover {
  color: var(--color-primary-font-hover);
}
.select :global .label-content:hover .icon {
  opacity: 1;
}
.select :global .icon svg {
  width: 0.8em;
}
.select :global .selection-list {
  max-height: 500px;
  box-shadow: 0 1px 4px 0 rgba(0, 0, 0, 0.2);
}
.select :global .selection-list li {
  text-align: center;
  line-height: 38px;
  font-size: 13px;
}
.select :global .selection-list li:hover {
  background-color: var(--color-button-background-hover);
}
.select :global .selection-list li:active {
  background-color: var(--color-button-background-active);
}
