/*自动隐藏文字*/
.main {
  position: relative;
  padding: 15px 0;
  min-width: 300px;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  overflow: hidden;
}
.main * {
  box-sizing: border-box;
}
.main h2 {
  flex: 0 0 none;
  font-size: 16px;
  color: var(--color-font);
  line-height: 1.3;
  text-align: center;
  margin-bottom: 15px;
}
.main h3 {
  font-size: 14px;
  line-height: 1.3;
}
.main pre {
  white-space: pre-wrap;
  text-align: justify;
  margin-top: 10px;
}
.info {
  flex: 1 1 auto;
  font-size: 14px;
  line-height: 1.5;
  overflow-y: auto;
  height: 100%;
  padding: 0 15px;
}
.current > p {
  padding-left: 15px;
}
.desc h3,
.desc h4 {
  font-weight: bold;
}
.desc h3 {
  padding: 5px 0 3px;
}
.desc ul {
  list-style: initial;
  padding-inline-start: 30px;
}
.desc p {
  font-size: 14px;
  line-height: 1.5;
}
.history h3 {
  padding-top: 15px;
}
.history .item {
  padding: 0 15px;
}
.history .item h3 {
  padding: 5px 0 3px;
}
.history .item + .item {
  padding-top: 15px;
}
.history .item h4 {
  font-weight: 700;
}
.history .item > p {
  padding-left: 15px;
}
.footer {
  flex: 0 0 none;
  padding: 0 15px;
}
.footer .desc {
  padding-top: 10px;
  font-size: 13px;
  color: var(--color-primary-font);
  line-height: 1.25;
}
.footer .desc p {
  font-size: 13px;
  color: var(--color-primary-font);
  line-height: 1.25;
}
.btns {
  display: flex;
  flex-flow: row nowrap;
  gap: 15px;
}
.btn {
  margin-top: 10px;
  display: block;
  width: 100%;
}
.btn2 {
  margin-top: 10px;
  display: block;
  width: 50%;
}
