/*自动隐藏文字*/
.main {
  flex: auto;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
}
.main h2 {
  margin: 20px;
  font-size: 16px;
  color: var(--color-font);
  line-height: 1.3;
  text-align: center;
}
.content {
  flex: auto;
  max-height: 100%;
  display: flex;
  padding: 0 15px;
}
.textarea {
  width: 100%;
  height: 100%;
  border: none;
  outline: none;
  border-radius: 4px;
  padding: 5px;
  background-color: var(--color-primary-light-200-alpha-900);
  box-sizing: border-box;
  font-family: inherit;
  resize: none;
}
.footer {
  box-sizing: border-box;
  flex: none;
  padding: 15px 15px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.tips {
  font-size: 12px;
  line-height: 1.25;
  color: var(--color-550);
  white-space: pre-wrap;
}
.btn {
  min-width: 80px;
}
