/*自动隐藏文字*/
.main {
  padding: 15px 8px;
  max-width: 550px;
  min-width: 300px;
  display: flex;
  flex-flow: column nowrap;
  min-height: 0;
}
.main h2 {
  font-size: 16px;
  color: var(--color-font);
  line-height: 1.3;
  text-align: center;
}
.name {
  color: var(--color-primary);
}
.checkbox {
  margin-top: 3px;
  font-size: 14px;
  opacity: 0.86;
}
.content {
  flex: auto;
  min-height: 80px;
  max-height: 100%;
  margin-top: 15px;
  padding: 0 7px;
}
.listItem {
  display: flex;
  flex-flow: row nowrap;
  align-items: center;
  transition: background-color 0.2s ease;
  padding: 15px 10px;
  border-radius: 4px;
}
.listItem:hover {
  background-color: var(--color-primary-background-hover);
}
.listItem.active {
  background-color: var(--color-primary-background-active);
}
.listItem h3 {
  font-size: 15px;
  color: var(--color-font);
  word-break: break-all;
}
.listItem h3 span {
  font-size: 12px;
  color: var(--color-font-label);
  margin-left: 6px;
}
.listItem p {
  margin-top: 5px;
  font-size: 14px;
  color: var(--color-font-label);
  word-break: break-all;
}
.noitem {
  height: 100px;
  font-size: 18px;
  color: var(--color-font-label);
  display: flex;
  justify-content: center;
  align-items: center;
}
.listLeft {
  flex: auto;
  min-width: 0;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
}
.listBtn {
  flex: none;
  height: 30px;
  width: 30px;
  padding: 0;
  display: flex;
  justify-content: center;
  align-items: center;
}
.listBtn svg {
  width: 60%;
}
.note {
  padding: 0 7px;
  margin-top: 15px;
  font-size: 12px;
  line-height: 1.25;
  color: var(--color-font);
}
.note p + p {
  margin-top: 5px;
}
.footer {
  padding: 0 7px;
  margin-top: 15px;
  display: flex;
  flex-flow: row nowrap;
}
.footerBtn {
  flex: auto;
  height: 36px;
  line-height: 36px;
  padding: 0 10px !important;
  width: 150px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.footerBtn + .footerBtn {
  margin-left: 15px;
}
.ruleLink {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
