/*自动隐藏文字*/
.theme {
  display: flex;
  flex-flow: row wrap;
  margin-bottom: -20px;
}
.theme .themeItem {
  display: flex;
  flex-flow: column nowrap;
  align-items: center;
  cursor: pointer;
  margin-right: 8px;
  transition: 0.3s ease;
  transition-property: color, opacity;
  margin-bottom: 18px;
  width: 86px;
}
.theme .themeItem:hover {
  opacity: 0.7;
}
.theme .themeItem:last-child {
  margin-right: 0;
}
.theme .themeItem.active {
  color: var(--color-primary-font-active);
}
.theme .themeItem.active .bg {
  border-color: var(--color-primary-font-active);
}
.theme .themeItem.active:hover {
  opacity: 1;
}
.theme .themeItem .bg {
  display: block;
  width: 36px;
  height: 36px;
  margin-bottom: 5px;
  border: 2Px solid transparent;
  padding: 2Px;
  transition: border-color 0.3s ease;
  border-radius: 5px;
}
.theme .themeItem .bg:after {
  display: block;
  content: ' ';
  width: 100%;
  height: 100%;
  border-radius: 4px;
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  background-color: var(--color-primary-theme);
  background-image: var(--background-image-theme);
}
.theme .themeItem .label {
  width: 100%;
  text-align: center;
  height: 1.2em;
}
.theme .themeItem.auto.active {
  color: var(--color-primary-font-active);
}
.theme .themeItem.auto.active .bg {
  border-color: var(--color-primary-font-active);
}
.theme .themeItem.auto > .bg:after {
  content: none;
}
.theme .themeItem.auto .bgContent {
  position: relative;
  height: 100%;
  overflow: hidden;
  border-radius: 5px;
}
.theme .themeItem.auto .light,
.theme .themeItem.auto .dark {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
}
.theme .themeItem.auto .light:after,
.theme .themeItem.auto .dark:after {
  display: block;
  content: ' ';
  width: 100%;
  height: 100%;
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
}
.theme .themeItem.auto .light:after {
  clip-path: polygon(0 0, 100% 0, 0 100%);
}
.theme .themeItem.auto .light svg {
  fill: var(--color-primary-theme-light);
}
.theme .themeItem.auto .light:after {
  background-color: var(--color-primary-theme-light);
  background-image: var(--background-image-theme-light);
}
.theme .themeItem.auto .dark:after {
  clip-path: polygon(0 100%, 100% 0, 100% 100%);
}
.theme .themeItem.auto .dark svg {
  fill: var(--color-primary-theme-dark);
}
.theme .themeItem.auto .dark:after {
  background-color: var(--color-primary-theme-dark);
  background-image: var(--background-image-theme-dark);
}
.theme .themeItem.add > .bg:after {
  content: none;
}
.theme .themeItem.add > .bg .bgContent {
  transition: 0.3s ease;
  transition-property: border, color;
  box-sizing: border-box;
  border: 1Px dashed var(--color-primary-light-100-alpha-300);
  color: var(--color-primary-light-100-alpha-300);
  position: relative;
  height: 100%;
  overflow: hidden;
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.theme .themeItem.add > .bg .icon {
  width: 66%;
  height: auto;
}
.theme .themeItem.add .label {
  color: var(--color-primary-dark-100-alpha-300);
}
.theme .themeItem.moreThme {
  flex-direction: row;
  width: auto;
  gap: 5px;
  color: var(--color-primary-font-active);
}
.theme .themeItem.moreThme .label {
  height: auto;
}
.sourceLabel {
  flex: auto;
  margin-left: 5px;
  line-height: 1.5;
  cursor: pointer;
}
.sourceLabel .desc {
  color: var(--color-500);
  font-size: 12px;
  margin-left: 5px;
}
.sourceLabel .status {
  margin-left: 5px;
}
