/*自动隐藏文字*/
.btnContent {
  flex: none;
  height: 100%;
}
.btn {
  position: relative;
  justify-content: center;
  align-items: center;
  transition: color 0.4s ease;
  cursor: pointer;
  background-color: transparent;
  border: none;
  width: 24px;
  display: flex;
  flex-flow: column nowrap;
  padding: 0;
}
.btn svg {
  transition: opacity 0.3s ease;
  opacity: 0.6;
  filter: drop-shadow(0 0 1px rgba(0, 0, 0, 0.2));
}
.btn:hover svg {
  opacity: 0.9;
}
.btn:active svg {
  opacity: 1;
}
.setting {
  display: flex;
  flex-flow: row nowrap;
  font-size: 14px;
  gap: 10px;
}
