/*自动隐藏文字*/
.content {
  flex: none;
  position: relative;
  padding: 15px 0;
}
.content:hover .progress {
  opacity: 1;
}
.timeContent {
  position: relative;
  color: var(--color-550);
  font-size: 13px;
  padding-bottom: 3px;
}
.progress {
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  flex: auto;
  margin-top: 2px;
  height: 2px;
  opacity: 0.24;
  overflow: hidden;
  transition: 0.4s ease;
  transition-property: background-color, opacity;
  background-color: var(--color-primary-light-100-alpha-800);
}
.progress .progressBar {
  height: 100%;
  width: 100%;
  background-color: var(--color-primary-light-100-alpha-400);
  transform-origin: 0;
  will-change: transform;
}
.progress .barTransition {
  transition-property: transform;
  transition-timing-function: ease-out;
  transition-duration: 0.2s;
}
.popupProgress {
  position: relative;
  width: 300px;
  height: 15px;
  box-sizing: border-box;
  padding: 5px 0;
  margin: 0 5px;
}
