/*自动隐藏文字*/
.main {
  min-width: 300px;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  min-height: 0;
}
.main h2 {
  flex: none;
  font-size: 16px;
  color: var(--color-font);
  line-height: 1.3;
  text-align: center;
  padding: 15px;
}
.main h3 {
  font-size: 16px;
  color: var(--color-font);
  line-height: 1.3;
  padding-bottom: 15px;
  font-size: 15px;
}
.content {
  flex: auto;
  font-size: 14px;
  gap: 5px;
  display: flex;
  flex-flow: column nowrap;
}
.groupTitle {
  padding: 20px 20px 0;
  display: flex;
  flex-flow: row wrap;
}
.groupTitle .title {
  margin-right: 5px;
}
.groupContent {
  display: flex;
  flex-flow: row wrap;
}
.item {
  padding: 15px 20px 0;
  width: 74px;
  display: flex;
  flex-flow: column nowrap;
  align-items: center;
}
.base .color {
  width: 100%;
}
.color {
  width: 80%;
  aspect-ratio: 1 / 1;
  background-color: var(--pcr-color);
  border-radius: 4px;
  cursor: pointer;
  transition: 0.3s ease !important;
  transition-property: background-color, opacity !important;
  box-shadow: 0 0 3px var(--color-primary-light-100-alpha-300);
}
.color:hover {
  opacity: 0.7;
}
.label {
  padding-top: 10px;
  text-align: center;
}
.bg {
  width: 150px;
}
.bgImg {
  width: 100%;
  height: 60px;
  border: 1Px dashed var(--color-primary-light-100-alpha-300);
  transition: 0.3s ease;
  transition-property: border, color;
  box-sizing: border-box;
  border: 1px dashed var(--color-primary-light-100-alpha-300);
  color: var(--color-primary-light-100-alpha-300);
  position: relative;
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: 0.3s ease !important;
  transition-property: background-color, opacity !important;
  overflow: hidden;
}
.bgImg:hover {
  opacity: 0.7;
}
.bgImg.hasBg {
  border: none;
}
.bgImg.hasBg .removeBtn {
  display: block;
}
.bgImg .img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.bgImg .removeBtn {
  position: absolute;
  right: 0;
  top: 0;
  border: none;
  cursor: pointer;
  padding: 6px 8px;
  background-color: rgba(0, 0, 0, 0.6);
  color: rgba(255, 255, 255, 0.9);
  outline: none;
  transition: background-color 0.2s ease;
  line-height: 0;
  display: none;
}
.bgImg .removeBtn svg {
  height: 0.7em;
}
.bgImg .removeBtn:hover {
  background-color: rgba(0, 0, 0, 0.7);
}
.bgImg .removeBtn:active {
  background-color: rgba(0, 0, 0, 0.8);
}
.bgImg .icon {
  width: auto;
  height: 66%;
}
.controlBtn {
  display: flex;
  -webkit-app-region: no-drag;
  align-items: center;
  padding: 0 14.04px;
  flex-direction: row-reverse;
  transition: opacity 0.4s ease;
  opacity: 0.5;
}
.controlBtn:hover {
  opacity: 0.8;
}
.controlBtn:hover .controlBtnIcon {
  opacity: 1;
}
.controlBtn button {
  position: relative;
  background: none;
  border: none;
  outline: none;
  padding: 1px;
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 14.04px;
  height: 14.04px;
  border-radius: 50%;
  color: var(--color-font);
}
.controlBtn button + button {
  margin-right: 7.02px;
}
.controlBtn button.hide {
  background-color: var(--color-btn-hide);
}
.controlBtn button.min,
.controlBtn button.fullscreenExit {
  background-color: var(--color-btn-min);
}
.controlBtn button.close {
  background-color: var(--color-btn-close);
}
.controlBtnIcon {
  opacity: 0;
  transition: opacity 0.2s ease-in-out;
}
.note {
  padding: 8px 15px;
  font-size: 13px;
  line-height: 1.25;
  color: var(--color-font);
}
.footer {
  padding: 15px;
  display: flex;
  flex-flow: row nowrap;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  font-size: 14px;
}
.footer .subContent {
  display: flex;
  flex-flow: row nowrap;
  align-items: center;
  gap: 10px;
}
.footer .checkbox {
  flex: none;
}
.footer .input {
  max-width: 150px;
  flex: 0 1 auto;
}
.btn {
  min-width: 70px;
}
