/*自动隐藏文字*/
.footer {
  flex: 0 0 100px;
  overflow: hidden;
  display: flex;
  align-items: center;
}
.footerLeft {
  flex: auto;
  display: flex;
  flex-flow: column nowrap;
  padding: 13px 13px 13px 30px;
  overflow: hidden;
}
.progressContainer {
  width: 100%;
  position: relative;
  padding: 3px 0;
}
.progressContent {
  position: relative;
  height: 16px;
  padding: 5px 0;
  width: 100%;
}
.progress {
  height: 100%;
}
.barTransition {
  transition-property: transform;
  transition-timing-function: ease-out;
  transition-duration: 0.2s;
}
.timeLabel {
  width: 100%;
  height: 18px;
  display: flex;
}
.timeLabel span {
  font-size: 13px;
}
.status {
  flex: auto;
}
.playControl {
  flex: none;
  height: 100%;
  display: flex;
  justify-content: flex-end;
  align-items: center;
  padding: 0 25px;
  color: var(--color-button-font);
}
.playBtn {
  height: 40%;
  padding: 5px;
  flex: none;
  color: var(--color-button-font);
  transition: opacity 0.2s ease;
  opacity: 1;
  cursor: pointer;
}
.playBtn + .playBtn {
  margin-left: 10px;
}
.playBtn svg {
  fill: currentColor;
  filter: drop-shadow(0 0 1px rgba(0, 0, 0, 0.2));
}
.playBtn:hover {
  opacity: 0.8;
}
.playBtn:active {
  opacity: 0.6;
}
