/*自动隐藏文字*/
.listsContent {
  flex: auto;
  min-width: 0;
  overflow-y: scroll;
}
.listsItem {
  position: relative;
  transition: 0.3s ease;
  transition-property: color, background-color;
  background-color: transparent;
}
.listsItem:hover:not(.active) {
  background-color: var(--color-primary-background-hover);
  cursor: pointer;
}
.listsItem.active {
  color: var(--color-primary);
}
.listsItem.selected {
  background-color: var(--color-primary-font-active);
}
.listsItem.clicked {
  background-color: var(--color-primary-background-hover);
}
.listsItem.editing {
  padding: 0 10px;
  background-color: var(--color-primary-background-hover);
}
.listsItem.editing .listsLabel {
  display: none;
}
.listsItem.editing .listsInput {
  display: block;
}
.activeIcon {
  height: 0.9em;
  width: 0.9em;
  margin-left: -0.45em;
  vertical-align: -0.05em;
}
.listsLabel {
  display: block;
  height: 100%;
  padding: 0 10px;
  font-size: 13px;
  line-height: 36px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
