/*自动隐藏文字*/
:global(.fullscreen) .header {
  -webkit-app-region: no-drag;
  align-self: flex-start;
}
:global(.fullscreen) .header .controBtn .close,
:global(.fullscreen) .header .controBtn .min {
  display: none;
}
:global(.fullscreen) .header .controBtn .fullscreenExit {
  display: flex;
}
.header {
  position: relative;
  flex: 0 0 54px;
  -webkit-app-region: drag;
  width: 100%;
}
.header .controBtn {
  position: absolute;
  top: 0;
  display: flex;
  -webkit-app-region: no-drag;
}
.header .controBtn button {
  position: relative;
  background: none;
  border: none;
  outline: none;
  padding: 1px;
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
}
.header .controBtn .fullscreenExit {
  display: none;
}
.header .controBtn {
  align-items: center;
  padding: 0 14.04px;
  left: 0;
  flex-direction: row-reverse;
  height: 37.8px;
  transition: opacity 0.4s ease;
  opacity: 0.5;
}
.header .controBtn.hover {
  opacity: 0.8;
}
.header .controBtn.hover .controBtnIcon {
  opacity: 1;
}
.header .controBtn button {
  width: 14.04px;
  height: 14.04px;
  border-radius: 50%;
  color: var(--color-font);
}
.header .controBtn button + button {
  margin-right: 7.02px;
}
.header .controBtn button.hide {
  background-color: var(--color-btn-hide);
}
.header .controBtn button.min,
.header .controBtn button.fullscreenExit {
  background-color: var(--color-btn-min);
}
.header .controBtn button.close {
  background-color: var(--color-btn-close);
}
.header .controBtnIcon {
  opacity: 0;
  transition: opacity 0.2s ease-in-out;
}
