/*自动隐藏文字*/
.contnet {
  padding-top: 15px;
  position: relative;
  display: flex;
  flex-flow: column nowrap;
  gap: 8px;
  min-height: 0;
  flex: none;
}
.contnet:before {
  display: block;
  content: '';
  position: absolute;
  top: 0;
  height: 1px;
  width: 100%;
  border-top: 1px dashed var(--color-primary-light-100-alpha-700);
}
.header {
  display: flex;
  flex-flow: row nowrap;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 5px;
}
.eqList {
  display: flex;
  flex-flow: column nowrap;
  gap: 15px;
  width: 100%;
}
.eqItem {
  display: flex;
  flex-flow: row nowrap;
  gap: 8px;
}
.label {
  flex: none;
  font-size: 12px;
}
.value {
  flex: none;
  width: 40px;
  font-size: 12px;
  text-align: center;
}
.value.active {
  color: var(--color-primary-font);
}
.footer {
  display: flex;
  flex-flow: row nowrap;
  justify-content: center;
  align-items: center;
}
.footer span {
  line-height: 1.2;
}
.slider {
  flex: auto;
}
.checkbox {
  margin-right: 10px;
  font-size: 13px;
}
.saveList {
  display: flex;
  flex-flow: row wrap;
  margin-top: 10px;
  gap: 10px;
}
