/*自动隐藏文字*/
.controlBtn {
  box-sizing: border-box;
  padding: 0 7px;
  display: flex;
  align-items: center;
  justify-content: space-evenly;
  width: 100%;
  height: 6%;
  -webkit-app-region: no-drag;
  opacity: 0.5;
  transition: opacity 0.4s ease;
}
.controlBtn.hover {
  opacity: 0.8;
}
.controlBtn.hover .controlBtniIcon {
  opacity: 1;
}
.btn {
  position: relative;
  width: 14.04px;
  height: 14.04px;
  background: none;
  border: none;
  display: flex;
  outline: none;
  padding: 1px;
  cursor: pointer;
  border-radius: 50%;
  color: var(--color-font);
}
.btn.min {
  background-color: var(--color-btn-min);
}
.btn.close {
  background-color: var(--color-btn-close);
}
.controlBtniIcon {
  opacity: 0;
  transition: opacity 0.2s ease-in-out;
}
