/*自动隐藏文字*/
.header {
  flex: none;
  padding: 15px;
  text-align: center;
}
.header h2 {
  word-break: break-all;
}
.main {
  min-height: 115px;
  width: 460px;
}
.list {
  font-size: 13px;
  transition-property: height;
  position: relative;
}
.list .listItem {
  position: relative;
  padding: 15px 10px 15px 15px;
  transition: 0.3s ease;
  transition-property: background-color, opacity;
  line-height: 1.3;
  display: flex;
  flex-flow: row nowrap;
  align-items: center;
}
.list .listItem:hover {
  background-color: var(--color-primary-background-hover);
}
.list .listItem.fetching {
  opacity: 0.5;
}
.listLeft {
  flex: auto;
  min-width: 0;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
}
.text {
  flex: auto;
  margin-bottom: 2px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.checkbox {
  margin-top: 3px;
  font-size: 14px;
  opacity: 0.86;
}
.label {
  flex: none;
  font-size: 12px;
  opacity: 0.5;
  padding: 0 10px;
}
.btns {
  flex: none;
  font-size: 12px;
  padding: 0 5px;
  display: flex;
  align-items: center;
}
.btn {
  background-color: transparent;
  border: none;
  border-radius: 3px;
  margin-right: 5px;
  cursor: pointer;
  padding: 4px 7px;
  color: var(--color-button-font);
  outline: none;
  transition: background-color 0.2s ease;
  line-height: 0;
}
.btn:last-child {
  margin-right: 0;
}
.btn svg {
  height: 22px;
  width: 22px;
}
.btn:hover {
  background-color: var(--color-primary-background-hover);
}
.btn:active {
  background-color: var(--color-primary-font-active);
}
.footer {
  width: 460px;
}
.tips {
  padding: 8px 15px;
  font-size: 13px;
  line-height: 1.25;
  color: var(--color-font);
}
.noItem {
  position: relative;
  height: 200px;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  align-items: center;
}
.noItem p {
  font-size: 16px;
  color: var(--color-font-label);
}
