/*自动隐藏文字*/
:global(.fullscreen) .header {
  -webkit-app-region: no-drag;
  align-self: flex-start;
}
:global(.fullscreen) .header .controBtn .close,
:global(.fullscreen) .header .controBtn .min {
  display: none;
}
:global(.fullscreen) .header .controBtn .fullscreenExit {
  display: flex;
}
.header {
  position: relative;
  flex: 0 0 54px;
  -webkit-app-region: drag;
  width: 100%;
  align-self: flex-start;
}
.header .controBtn {
  position: absolute;
  top: 0;
  display: flex;
  -webkit-app-region: no-drag;
}
.header .controBtn button {
  position: relative;
  background: none;
  border: none;
  outline: none;
  padding: 1px;
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
}
.header .controBtn .fullscreenExit {
  display: none;
}
.header .controBtn {
  right: 0;
}
.header .controBtn button {
  width: 46px;
  height: 30px;
  color: var(--color-font-label);
  transition: background-color 0.2s ease-in-out;
}
.header .controBtn button.hover {
  background-color: var(--color-button-background-hover);
}
.header .controBtn button.hover.close {
  background-color: var(--color-btn-close);
}
