/*自动隐藏文字*/
.right {
  flex: 0 0 60%;
  position: relative;
  transition: flex-basis 0.4s ease;
}
.lyric {
  text-align: center;
  height: 100%;
  overflow: hidden;
  font-size: var(--playDetail-lrc-font-size, 16px);
  -webkit-mask-image: linear-gradient(transparent 0%, #fff 20%, #fff 80%, transparent 100%);
  cursor: grab;
}
.lyric.draging {
  cursor: grabbing;
}
.lyric :global .font-lrc {
  color: var(--color-450);
}
.lyric :global .line-content {
  line-height: 1.2;
  padding: calc(var(--playDetail-lrc-font-size, 16px) / 2) 1px;
  overflow-wrap: break-word;
  color: var(--color-450);
  transition: 0.4s ease;
  transition-property: padding;
}
.lyric :global .line-content .extended {
  font-size: 0.8em;
  margin-top: 5px;
}
.lyric :global .line-content.line-mode .font-lrc {
  transition: 0.3s ease;
  transition-property: font-size, color;
}
.lyric :global .line-content.line-mode.active .font-lrc,
.lyric :global .line-content.font-mode.played .font-lrc {
  color: var(--color-primary-dark-200);
}
.lyric :global .line-content.font-mode .extended .font-lrc {
  transition: 0.6s ease;
  transition-property: font-size, color;
}
.lyric :global .line-content.font-mode > .line > .font-lrc > span {
  transition: 0.4s ease;
  transition-property: font-size;
  font-size: 1em;
  background-repeat: no-repeat;
  background-color: var(--color-450);
  background-image: -webkit-linear-gradient(top, var(--color-primary-dark-200), var(--color-primary-dark-200));
  -webkit-text-fill-color: transparent;
  -webkit-background-clip: text;
  background-size: 0 100%;
}
.lrcActiveZoom :global .line-content.active .extended {
  font-size: 0.94em;
}
.lrcActiveZoom :global .line-content.active .line {
  font-size: 1.1em;
}
.skip {
  position: absolute;
  top: calc(38% + var(--playDetail-lrc-font-size, 16px) + 4px);
  left: 0;
  width: 100%;
  pointer-events: none;
}
.skip .line {
  border-top: 2px dotted var(--color-primary-dark-100);
  opacity: 0.15;
  margin-right: 30px;
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, transparent 15%, #fff 100%);
}
.skip .label {
  position: absolute;
  right: 30px;
  top: -14px;
  line-height: 1.2;
  font-size: 12px;
  color: var(--color-primary-dark-100);
  opacity: 0.7;
}
.skip .skipBtn {
  position: absolute;
  right: 0;
  top: 0;
  transform: translateY(-50%);
  width: 30px;
  height: 30px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: none !important;
  pointer-events: initial;
  transition: 0.4s ease;
  transition-property: opacity;
  opacity: 0.8;
}
.skip .skipBtn:hover {
  opacity: 0.6;
}
.lyricSelectContent {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  width: 100%;
  font-size: var(--playDetail-lrc-font-size, 16px);
  z-index: 10;
  color: var(--color-400);
}
.lyricSelectContent .lyricSelectline {
  padding: calc(var(--playDetail-lrc-font-size, 16px) / 2) 1px;
  overflow-wrap: break-word;
  transition: 0.4s ease !important;
  transition-property: color, font-size;
  line-height: 1.3;
}
.lyricSelectContent .lyricSelectlineExtended {
  font-size: 14px;
}
.lyricSelectContent .lrcActive {
  color: var(--color-primary);
}
.lyricSpace {
  height: 70%;
}
