/*自动隐藏文字*/
.btn {
  position: relative;
  justify-content: center;
  align-items: center;
  transition: color 0.4s ease;
  cursor: pointer;
  background-color: transparent;
  border: none;
  width: 24px;
  display: flex;
  flex-flow: column nowrap;
  padding: 0;
}
.btn svg {
  transition: opacity 0.3s ease;
  opacity: 0.6;
  filter: drop-shadow(0 0 1px rgba(0, 0, 0, 0.2));
}
.btn:hover svg {
  opacity: 0.9;
}
.btn:active svg {
  opacity: 1;
}
.main {
  min-width: 300px;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  min-height: 0;
}
.content {
  display: flex;
  flex-flow: row nowrap;
  padding: 0 5px;
  margin: 15px 0;
  gap: 10px;
  position: relative;
  min-height: 0;
}
.content:before {
  display: block;
  content: '';
  position: absolute;
  left: 50%;
  height: 100%;
  border-left: 1px dashed var(--color-primary-light-100-alpha-700);
}
.content :global .player__sound_effect_title {
  font-size: 14px;
  padding-bottom: 8px;
}
.row {
  width: 50%;
  display: flex;
  gap: 15px;
  flex-flow: column nowrap;
  padding: 0 10px;
}
.tip {
  padding: 0 15px 15px;
  margin-top: 5px;
  font-size: 12px;
  line-height: 1.25;
  color: var(--color-font);
}
