/*自动隐藏文字*/
.select {
  display: inline-block;
  font-size: 12px;
  position: relative;
  width: var(--selection-width, 300px);
}
.select.active .label {
  background-color: var(--color-button-background);
}
.select.active .list {
  opacity: 1;
}
.select.active .icon svg {
  transform: rotate(180deg);
}
.label {
  background-color: var(--color-button-background);
  padding: 0 10px;
  transition: background-color 0.4s ease;
  height: 28px;
  line-height: 1.5;
  box-sizing: border-box;
  color: var(--color-button-font);
  border-radius: 3px;
  cursor: pointer;
  display: flex;
  align-items: center;
}
.label span {
  flex: auto;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.label .icon {
  flex: none;
  margin-left: 7px;
  line-height: 0;
}
.label .icon svg {
  width: 1em;
  transition: transform 0.2s ease;
  transform: rotate(0);
}
.label:hover {
  background-color: var(--color-button-background-hover);
}
.label:active {
  background-color: var(--color-button-background-active);
}
.list {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  background-color: var(--color-content-background);
  opacity: 0;
  transform: scaleY(0) translateY(0);
  transform-origin: 0 14px 0;
  transition: 0.25s ease;
  transition-property: transform, opacity;
  z-index: 10;
  border-radius: 3px;
  box-shadow: 0 0 4px rgba(0, 0, 0, 0.15);
  overflow: auto;
  max-height: 200px;
}
.listItem {
  cursor: pointer;
  padding: 0 10px;
  line-height: 28px;
  outline: none;
  transition: background-color 0.4s ease;
  background-color: transparent;
  box-sizing: border-box;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.listItem:hover {
  background-color: var(--color-button-background-hover);
}
.listItem:active {
  background-color: var(--color-button-background-active);
}
.listItem.active {
  color: var(--color-button-font);
}
