/*自动隐藏文字*/
.newPreset {
  position: relative;
  border: 1px dashed var(--color-primary-font-hover);
  color: var(--color-primary-font-hover);
  opacity: 0.7;
  height: 22px;
}
.newPreset.editing {
  opacity: 1;
  width: 90px;
}
.newPreset.editing svg {
  display: none;
}
.newPreset.editing .newPresetInput {
  display: block;
}
.newPreset :global .svg-icon {
  vertical-align: 0;
}
.newPresetInput {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  background: none !important;
  font-size: 12px;
  text-align: center;
  font-family: inherit;
  box-sizing: border-box;
  padding: 0 3px;
  border-radius: 0;
  display: none;
}
.newPresetInput::placeholder {
  font-size: 12px;
}
