/*自动隐藏文字*/
.contnet {
  display: flex;
  flex-flow: column nowrap;
  gap: 8px;
  min-height: 0;
  flex: none;
}
.header {
  display: flex;
  flex-flow: row nowrap;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 5px;
}
.eqList {
  display: flex;
  flex-flow: row wrap;
  width: 100%;
  justify-content: space-between;
  position: relative;
}
.eqList:before {
  display: block;
  content: '';
  position: absolute;
  left: 50%;
  height: 100%;
  border-left: 1px dashed var(--color-primary-light-100-alpha-700);
}
.eqItem {
  display: flex;
  flex-flow: row nowrap;
  width: 50%;
  gap: 8px;
  margin-bottom: 15px;
  box-sizing: border-box;
}
.eqItem:nth-child(odd) {
  padding-right: 10px;
}
.eqItem:nth-child(even) {
  padding-left: 10px;
}
.eqItem:nth-last-child(1),
.eqItem:nth-last-child(2) {
  margin-bottom: 0;
}
.label {
  flex: none;
  width: 40px;
  font-size: 12px;
  text-align: center;
}
.value {
  flex: none;
  width: 40px;
  font-size: 12px;
  text-align: center;
}
.footer {
  display: flex;
  flex-flow: row nowrap;
  justify-content: center;
  align-items: center;
}
.footer span {
  line-height: 1.2;
}
.slider {
  flex: auto;
}
.saveList {
  display: flex;
  flex-flow: row wrap;
  margin-top: 10px;
  gap: 10px;
}
