/*自动隐藏文字*/
.main {
  padding: 15px;
  max-width: 400px;
  min-width: 200px;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
}
.main h2 {
  font-size: 13px;
  color: var(--color-font);
  line-height: 1.3;
  text-align: center;
  margin-bottom: 15px;
}
.btn {
  display: block;
  margin-bottom: 15px;
}
.btn:last-child {
  margin-bottom: 0;
}
