/*自动隐藏文字*/
.main {
  min-width: 460px;
  min-height: 200px;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
}
.main h2 {
  margin: 15px;
  font-size: 16px;
  color: var(--color-font);
  line-height: 1.3;
  text-align: center;
}
.name {
  color: var(--color-font);
  font-size: 14px;
  word-break: break-all;
  line-height: 1.2;
}
.desc {
  color: var(--color-font-label);
  margin-top: 8px;
  font-size: 12px;
  word-break: break-all;
}
.content {
  flex: auto;
  min-height: 100px;
  max-height: 100%;
}
.listItem {
  display: flex;
  flex-flow: row nowrap;
  align-items: center;
  transition: background-color 0.2s ease;
  padding: 10px;
}
.listItem:hover {
  background-color: var(--color-primary-background-hover);
}
.noitem {
  height: 100px;
  font-size: 18px;
  color: var(--color-font-label);
  display: flex;
  justify-content: center;
  align-items: center;
}
.listLeft {
  flex: auto;
  min-width: 0;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
}
.listBtn {
  flex: none;
  height: 30px;
  width: 30px;
  padding: 0;
  display: flex;
  justify-content: center;
  align-items: center;
}
.listBtn svg {
  width: 60%;
}
.tips {
  padding: 8px 15px;
  font-size: 13px;
  line-height: 1.25;
  color: var(--color-font);
}
