/*自动隐藏文字*/
.control {
  display: flex;
  align-self: flex-start;
  -webkit-app-region: no-drag;
  height: 30px;
}
.control .btn {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  width: 46px;
  height: 30px;
  background: none;
  border: none;
  outline: none;
  padding: 1px;
  cursor: pointer;
  color: var(--color-font-label);
  transition: background-color 0.2s ease-in-out;
}
.control .btn.hover.min,
.control .btn.hover.max {
  background-color: var(--color-button-background-hover);
}
.control .btn.hover.close {
  background-color: var(--color-btn-close);
}
