/*自动隐藏文字*/
.checkbox {
  display: inline-block;
}
.input {
  display: none;
}
.input[disabled] + .content {
  opacity: 0.5;
}
.input[disabled] + .content .container,
.input[disabled] + .content .label {
  cursor: default;
}
.input:checked + .content .container:after {
  border-color: var(--color-primary-font);
}
.input:checked + .content .icon {
  transform: scale(1);
}
.content {
  display: flex;
  align-items: center;
}
.container {
  flex: none;
  position: relative;
  width: 1em;
  height: 1em;
  cursor: pointer;
  display: flex;
  color: var(--color-primary);
}
.container:after {
  position: absolute;
  content: ' ';
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  border: 1px solid var(--color-font-label);
  transition: border-color 0.2s ease;
  border-radius: 2px;
}
.icon {
  transition: 0.3s ease;
  transition-property: transform;
  transform: scale(0);
  border-radius: 2px;
}
.label {
  flex: auto;
  margin-left: 5px;
  line-height: 1.5;
  cursor: pointer;
}
