/*自动隐藏文字*/
.container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 99;
}
.modal {
  width: 100%;
  height: 100%;
  display: grid;
  align-items: center;
  justify-items: center;
}
.modal.filter {
  backdrop-filter: grayscale(70%);
}
.content {
  border-radius: 4px;
  box-shadow: 0 0 4px rgba(0, 0, 0, 0.25);
  overflow: hidden;
  min-width: 220px;
  position: relative;
  display: flex;
  flex-flow: column nowrap;
  z-index: 100;
  background-color: var(--color-content-background);
}
.header {
  flex: none;
  background-color: var(--color-primary-light-100-alpha-100);
  display: flex;
  align-items: center;
  justify-content: flex-end;
  height: 18px;
}
.header button {
  border: none;
  cursor: pointer;
  padding: 4px 7px;
  background-color: transparent;
  color: var(--color-primary-dark-500-alpha-500);
  outline: none;
  transition: background-color 0.2s ease;
  line-height: 0;
}
.header button svg {
  height: 0.7em;
}
.header button:hover {
  background-color: var(--color-primary-dark-100-alpha-600);
}
.header button:active {
  background-color: var(--color-primary-dark-200-alpha-600);
}
