/*自动隐藏文字*/
.container {
  display: flex;
  flex-flow: column nowrap;
}
.songListHeader {
  flex: none;
  display: flex;
  flex-flow: row nowrap;
  height: 80px;
}
.songListHeaderLeft {
  flex: none;
  margin-left: 15px;
  height: 100%;
  aspect-ratio: 1 / 1;
  position: relative;
  overflow: hidden;
  border-radius: 4px;
  background-position: center;
  background-size: cover;
  opacity: 0.9;
  box-shadow: 0 0 2px 0 rgba(0, 0, 0, 0.2);
}
.playNum {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 4px;
  background-color: rgba(0, 0, 0, 0.4);
  color: #fff;
  font-size: 12px;
  text-align: right;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.songListHeaderMiddle {
  flex: auto;
  padding: 2px 7px;
  min-width: 0;
}
.songListHeaderMiddle h3 {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  line-height: 1.2;
  padding-bottom: 5px;
  color: var(--color-font);
}
.songListHeaderMiddle p {
  display: -webkit-box;
  overflow: hidden;
  text-overflow: ellipsis;
  word-wrap: break-word;
  word-break: break-all;
  white-space: normal !important;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  font-size: 12px;
  line-height: 1.2;
  color: var(--color-font-label);
}
.songListHeaderRight {
  flex: none;
  display: flex;
  align-items: center;
  padding-right: 15px;
}
.songListHeaderRight .headerRightBtn {
  border-radius: 0;
}
.songListHeaderRight .headerRightBtn:first-child {
  border-top-left-radius: 4px;
  border-bottom-left-radius: 4px;
}
.songListHeaderRight .headerRightBtn:last-child {
  border-top-right-radius: 4px;
  border-bottom-right-radius: 4px;
}
.list {
  position: relative;
  width: 100%;
  min-height: 0;
  flex: auto;
  height: 100%;
}
