/*自动隐藏文字*/
.container {
  overflow: hidden;
  height: 100%;
  display: flex;
  flex-flow: column nowrap;
  position: relative;
}
.listContent {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  display: flex;
  flex-flow: column nowrap;
  font-size: 14px;
  box-sizing: border-box;
  padding: 0 15px;
}
.listContent ul {
  display: flex;
  flex-flow: row wrap;
  justify-content: space-between;
}
.item {
  width: 32%;
  box-sizing: border-box;
  display: flex;
  margin-top: 15px;
  cursor: pointer;
  transition: opacity 0.4s ease;
}
.item:hover {
  opacity: 0.7;
}
.left {
  flex: none;
  width: 88px;
  height: 88px;
  display: flex;
  background-position: center;
  background-size: cover;
  border-radius: 4px;
  overflow: hidden;
  opacity: 0.9;
}
.left img {
  object-fit: cover;
}
.right {
  flex: auto;
  padding: 3px 15px 5px 7px;
  overflow: hidden;
}
.right h4 {
  font-size: 14px;
  height: 2.6em;
  text-align: justify;
  line-height: 1.3;
  display: -webkit-box;
  overflow: hidden;
  text-overflow: ellipsis;
  word-wrap: break-word;
  word-break: break-all;
  white-space: normal !important;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.songlist_info {
  display: flex;
  flex-flow: row nowrap;
  gap: 15px;
  margin-top: 12px;
  font-size: 12px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  text-align: justify;
  line-height: 1.2;
  color: var(--color-font-label);
}
.songlist_info svg {
  margin-right: 2px;
}
.author {
  margin-top: 6px;
  font-size: 12px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  text-align: justify;
  line-height: 1.2;
  color: var(--color-font-label);
}
.pagination {
  text-align: center;
  padding: 15px 0;
}
.noitem {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 100%;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  align-items: center;
}
.noitem p {
  font-size: 24px;
  color: var(--color-font-label);
}
