/*自动隐藏文字*/
.lists {
  flex: none;
  width: 16%;
  display: flex;
  flex-flow: column nowrap;
}
.listHeader {
  position: relative;
  display: flex;
  flex-flow: row nowrap;
  border-bottom: var(--color-list-header-border-bottom);
}
.listHeader:hover .listsAdd {
  opacity: 1;
}
.listsTitle {
  flex: auto;
  font-size: 12px;
  line-height: 38px;
  padding: 0 10px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.headerBtns {
  flex: none;
  display: flex;
}
.listsAdd {
  margin-top: 6px;
  background: none;
  height: 30px;
  border: none;
  outline: none;
  border-radius: 4px;
  cursor: pointer;
  opacity: 0.1;
  transition: opacity 0.4s ease;
  color: var(--color-button-font);
}
.listsAdd svg {
  vertical-align: bottom;
}
.listsAdd:active {
  opacity: 0.7 !important;
}
.listsAdd:hover {
  opacity: 0.6 !important;
}
.listsContent {
  flex: auto;
  min-width: 0;
  overflow-y: scroll !important;
}
.listsContent.sortable * {
  -webkit-user-drag: element;
}
.listsContent.sortable .listsItem:hover,
.listsContent.sortable .listsItem.active,
.listsContent.sortable .listsItem.selected,
.listsContent.sortable .listsItem.clicked {
  background-color: transparent !important;
}
.listsContent.sortable .listsItem.dragingItem {
  background-color: var(--color-primary-background-hover) !important;
}
.listsItem {
  position: relative;
  transition: 0.3s ease;
  transition-property: color, background-color, opacity;
  background-color: transparent;
}
.listsItem:not(.active):hover {
  background-color: var(--color-primary-background-hover);
  cursor: pointer;
}
.listsItem.active {
  color: var(--color-primary);
}
.listsItem.selected {
  background-color: var(--color-primary-font-active);
}
.listsItem.clicked {
  background-color: var(--color-primary-background-hover);
}
.listsItem.fetching {
  opacity: 0.5;
}
.listsItem.editing {
  padding: 0 10px;
  background-color: var(--color-primary-background-hover);
}
.listsItem.editing .listsLabel {
  display: none;
}
.listsItem.editing .listsInput {
  display: block;
}
.activeIcon {
  height: 0.9em;
  width: 0.9em;
  margin-left: -0.45em;
  vertical-align: -0.05em;
}
.listsLabel {
  display: block;
  height: 36px;
  padding: 0 10px;
  font-size: 13px;
  line-height: 36px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.listsInput {
  width: 100%;
  height: 36px;
  padding: 0;
  line-height: 36px;
  background: none !important;
  border-radius: 0;
  font-size: 13px;
  display: none;
}
.listsNew {
  padding: 0 10px;
  background-color: var(--color-primary-background-hover) !important;
}
.listsNew .listsInput {
  display: block;
}
.newLeave {
  margin-top: -36px;
  z-index: -1;
}
