/*自动隐藏文字*/
.main {
  padding: 0 15px;
  display: flex;
  flex-flow: column nowrap;
  min-height: 0;
}
.main h2 {
  font-size: 14px;
  color: var(--color-font);
  line-height: 1.3;
  word-break: break-all;
  padding: 15px 0 8px;
}
.inputContent {
  display: flex;
  flex-flow: row nowrap;
}
.select {
  width: auto;
}
.select :global .label-content {
  height: 100%;
  border-top-right-radius: 0;
  border-bottom-right-radius: 0;
}
.select :global .selection-list li {
  text-align: center;
  line-height: 32px;
  font-size: 13px;
}
.select :global .selection-list li:hover {
  background-color: var(--color-button-background-hover);
}
.select :global .selection-list li:active {
  background-color: var(--color-button-background-active);
}
.input {
  flex: auto;
  border-top-left-radius: 0;
  border-bottom-left-radius: 0;
  padding: 8px 8px;
  color: var(--color-font);
}
.footer {
  margin: 50px 0 15px;
  display: flex;
  flex-flow: row nowrap;
  align-items: flex-end;
}
.tips {
  flex: auto;
  font-size: 12px;
  color: var(--color-font);
  line-height: 1.5;
}
.tips ul {
  list-style: decimal;
  padding-left: 15px;
}
.btn {
  min-width: 80px;
}
