/*自动隐藏文字*/
.pagination {
  display: inline-block;
  background-color: var(--color-button-background);
  border-radius: 4px;
}
.pagination ul {
  display: flex;
  flex-flow: row nowrap;
}
.pagination ul li {
  transition: 0.4s ease;
  transition-property: all;
  line-height: 1.2;
  display: flex;
}
.pagination ul li svg {
  height: 1em;
}
.pagination ul li span,
.pagination ul li button {
  display: block;
  padding: 7px 12px;
  line-height: 1.2;
  color: var(--color-button-font);
  font-size: 13px;
}
.pagination ul li.active span {
  background-color: var(--color-button-background-selected);
}
.pagination ul li button {
  background-color: transparent;
  border: none;
  cursor: pointer;
  outline: none;
  transition: background-color 0.3s ease;
}
.pagination ul li button:hover {
  background-color: var(--color-button-background-hover);
}
.pagination ul li button:active {
  background-color: var(--color-button-background-active);
}
.pagination ul li.disabled span {
  opacity: 0.3;
}
.pagination ul li:first-child span,
.pagination ul li:first-child button {
  border-top-left-radius: 4px;
  border-bottom-left-radius: 4px;
}
.pagination ul li:last-child span,
.pagination ul li:last-child button {
  border-top-right-radius: 4px;
  border-bottom-right-radius: 4px;
}
.pagination ul li:first-child span,
.pagination ul li:last-child span,
.pagination ul li.first span,
.pagination ul li.last span,
.pagination ul li:first-child button,
.pagination ul li:last-child button,
.pagination ul li.first button,
.pagination ul li.last button {
  line-height: 0;
}
