/*自动隐藏文字*/
.main {
  padding: 0 15px;
  width: 450px;
  min-width: 280px;
  display: flex;
  flex-flow: column nowrap;
  min-height: 0;
}
.main h2 {
  font-size: 13px;
  color: var(--color-font);
  line-height: 1.3;
  word-break: break-all;
  padding: 15px 0 8px;
}
.input {
  padding: 8px 8px;
}
.footer {
  margin: 20px 0 15px auto;
}
.btn {
  min-width: 70px;
}
.btn + .btn {
  margin-left: 10px;
}
