/*自动隐藏文字*/
.portInput[disabled],
.hostInput[disabled] {
  opacity: 0.8 !important;
}
.hostInput {
  min-width: 380px;
}
.list {
  font-size: 13px;
  transition-property: height;
  position: relative;
}
.list .listItem {
  position: relative;
  padding: 15px 10px 15px 15px;
  transition: 0.3s ease;
  transition-property: background-color, opacity;
  line-height: 1.3;
  display: flex;
  flex-flow: row nowrap;
  align-items: center;
}
.list .listItem:hover {
  background-color: var(--color-primary-background-hover);
}
.list .listItem.fetching {
  opacity: 0.5;
}
.listLeft {
  flex: auto;
  min-width: 0;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
}
.text {
  flex: auto;
  margin-bottom: 2px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.label {
  flex: none;
  font-size: 12px;
  opacity: 0.5;
}
.btns {
  flex: none;
  font-size: 12px;
  padding: 0 5px;
  display: flex;
  align-items: center;
}
.btn {
  background-color: transparent;
  border: none;
  border-radius: 3px;
  margin-right: 5px;
  cursor: pointer;
  padding: 4px 7px;
  color: var(--color-button-font);
  outline: none;
  transition: background-color 0.2s ease;
  line-height: 0;
}
.btn:last-child {
  margin-right: 0;
}
.btn svg {
  height: 22px;
  width: 22px;
}
.btn:hover {
  background-color: var(--color-primary-background-hover);
}
.btn:active {
  background-color: var(--color-primary-font-active);
}
