/*自动隐藏文字*/
.btnContent {
  flex: none;
  height: 100%;
}
.btn {
  position: relative;
  justify-content: center;
  align-items: center;
  transition: color 0.4s ease;
  cursor: pointer;
  background-color: transparent;
  border: none;
  width: 24px;
  display: flex;
  flex-flow: column nowrap;
  padding: 0;
}
.btn svg {
  transition: opacity 0.3s ease;
  opacity: 0.5;
}
.btn:hover svg {
  opacity: 0.9;
}
.btn:active svg {
  opacity: 1;
}
.btn.active svg {
  color: var(--color-primary);
  opacity: 0.8;
}
.setting {
  display: flex;
  flex-flow: column nowrap;
  padding: 2px 3px;
  gap: 8px;
  width: 300px;
}
.info {
  display: flex;
  flex-flow: row nowrap;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
}
.info span {
  line-height: 1.2;
}
.control {
  align-items: center;
  display: flex;
  gap: 10px;
}
.slider {
  width: 100%;
}
