/*自动隐藏文字*/
.controlBtn {
  padding-left: 20px;
  padding-right: 10px;
  flex: none;
  display: flex;
  flex-flow: row nowrap;
  gap: 10px;
}
.controlBtn button {
  color: var(--color-button-font);
}
.titleBtn {
  flex: none;
  height: 100%;
  transition: 0.3s ease;
  transition-property: color, opacity;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  align-items: center;
  background-color: transparent;
  border: none;
  width: 24px;
  padding: 0;
  opacity: 0.6;
  cursor: pointer;
}
.titleBtn svg {
  filter: drop-shadow(0 0 1px rgba(0, 0, 0, 0.2));
}
.titleBtn:hover {
  opacity: 1;
}
.titleBtn:active {
  opacity: 1;
}
