/*自动隐藏文字*/
.player {
  position: relative;
  height: 66px;
  box-sizing: border-box;
  display: flex;
  flex-flow: row nowrap;
  align-items: center;
  contain: strict;
  padding: 8px 6px 6px;
  z-index: 2;
}
.player * {
  box-sizing: border-box;
}
.player:before {
  display: block;
  position: absolute;
  content: '';
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  background-color: var(--color-main-background);
  opacity: 0.9;
  z-index: -1;
}
.progress {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  padding-bottom: 6px;
}
.progress .progressBar {
  height: 2px;
  border-radius: 0;
}
.picContent {
  height: 100%;
  aspect-ratio: 1 / 1;
  flex: none;
  opacity: 1;
  transition: opacity 0.3s ease;
  display: flex;
  justify-content: center;
  cursor: pointer;
}
.picContent:hover {
  opacity: 0.8;
}
.picContent img {
  box-shadow: 0 0 2px rgba(0, 0, 0, 0.3);
  max-width: 100%;
  max-height: 100%;
  transition: 0.4s ease;
  transition-property: border-color;
  border-radius: 4px;
}
.picContent .emptyPic {
  background-color: var(--color-primary-light-900-alpha-200);
  border-radius: 4px;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary-light-400-alpha-200);
  user-select: none;
  font-size: 20px;
  font-family: Consolas, "Courier New", monospace;
}
.picContent .emptyPic span {
  padding-left: 3px;
}
.infoContent {
  padding-left: 10px;
  flex: auto;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  align-items: flex-start;
  font-size: 13px;
  color: var(--color-font);
  min-width: 0;
  line-height: 1.5;
}
.title {
  max-width: 100%;
  font-size: 12px;
  color: var(--color-font-label);
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.status {
  padding-top: 3px;
  height: 23px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  max-width: 100%;
}
.timeContent {
  flex: none;
  color: var(--color-550);
  font-size: 13px;
  padding-left: 10px;
}
.playBtnContent {
  height: 100%;
  flex: none;
  display: flex;
  flex-flow: row nowrap;
  align-items: center;
  padding-left: 10px;
  padding-right: 15px;
  gap: 18px;
}
.playBtn {
  flex: none;
  height: 52%;
  transition: 0.3s ease;
  transition-property: color, opacity;
  color: var(--color-button-font);
  opacity: 1;
  cursor: pointer;
}
.playBtn svg {
  fill: currentColor;
  filter: drop-shadow(0 0 1px rgba(0, 0, 0, 0.2));
}
.playBtn:hover {
  opacity: 0.8;
}
.playBtn:active {
  opacity: 0.6;
}
