/*自动隐藏文字*/
.main {
  min-width: 300px;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  min-height: 0;
}
.main h2 {
  flex: none;
  font-size: 16px;
  color: var(--color-font);
  line-height: 1.3;
  text-align: center;
  padding: 15px;
}
.main h3 {
  font-size: 16px;
  color: var(--color-font);
  line-height: 1.3;
  padding-bottom: 15px;
  font-size: 15px;
}
.content {
  flex: auto;
  padding: 15px;
  display: flex;
  flex-flow: column nowrap;
  gap: 15px;
}
.theme {
  display: flex;
  flex-flow: row wrap;
}
.theme li {
  display: flex;
  flex-flow: column nowrap;
  align-items: center;
  cursor: pointer;
  margin-right: 4px;
  transition: color 0.3s ease;
  margin-bottom: 15px;
  width: 86px;
}
.theme li:last-child {
  margin-right: 0;
}
.theme li.active {
  color: var(--color-primary-theme);
}
.theme li.active .bg {
  border-color: var(--color-primary-theme);
}
.theme li .bg {
  display: block;
  width: 36px;
  height: 36px;
  margin-bottom: 5px;
  border: 2px solid transparent;
  padding: 2px;
  transition: border-color 0.3s ease;
  border-radius: 5px;
}
.theme li .bg:after {
  display: block;
  content: ' ';
  width: 100%;
  height: 100%;
  border-radius: 4px;
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  background-color: var(--color-primary-theme);
  background-image: var(--background-image-theme);
}
.theme li label {
  width: 100%;
  text-align: center;
  height: 1.2em;
  font-size: 14px;
}
.note {
  padding: 8px 15px;
  font-size: 13px;
  line-height: 1.25;
  color: var(--color-font);
}
