/*自动隐藏文字*/
.list {
  overflow: hidden;
  height: 100%;
  flex: auto;
  display: flex;
  flex-flow: column nowrap;
}
.list :global(.list-item).active {
  color: var(--color-button-font);
}
.list :global .label-source {
  color: var(--color-primary);
  padding: 5px;
  font-size: 0.8em;
  line-height: 1.2;
  opacity: 0.75;
  display: inline-block;
}
.num {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.playIcon {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-button-font);
  opacity: 0.7;
}
.content {
  min-height: 0;
  font-size: 14px;
  display: flex;
  flex-flow: column nowrap;
  flex: auto;
}
.noItem {
  position: relative;
  height: 100%;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  align-items: center;
}
.noItem p {
  font-size: 24px;
  color: var(--color-font-label);
}
