/*自动隐藏文字*/
.noitem {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 100%;
  overflow: hidden;
  display: flex;
  flex-flow: column nowrap;
}
.noitemListContainer {
  padding: 3% 15px 15px;
  min-height: 250px;
  max-height: 94.7%;
}
.noitemList + .noitemList {
  margin-top: 15px;
}
.noitemHotSearchList {
  min-height: 106px;
}
.noitemListTitle {
  color: var(--color-font);
  padding: 5px 5px 8px;
  font-size: 14px;
}
.noitemListItem {
  display: inline-block;
  margin: 3px 5px;
  background-color: var(--color-button-background);
  padding: 7px 10px;
  border-radius: 5px;
  transition: background-color 0.4s ease;
  cursor: pointer;
  color: var(--color-button-font);
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  max-width: 150px;
  font-size: 13px;
}
.noitemListItem:hover {
  background-color: var(--color-button-background-hover);
}
.noitemListItem:active {
  background-color: var(--color-button-background-active);
}
.historyClearBtn {
  padding: 0 5px;
  margin-left: 5px;
  color: var(--color-font-label);
  cursor: pointer;
  transition: 0.4s ease;
  transition-property: color, opacity;
  opacity: 0.3;
}
.historyClearBtn:hover {
  color: var(--color-primary-font-hover);
  opacity: 0.8;
}
.historyClearBtn:active {
  color: var(--color-primary-font-active);
  opacity: 1;
}
.historyClearBtn svg {
  vertical-align: middle;
  width: 15px;
}
.noitem_label {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.noitem_label p {
  font-size: 24px;
  color: var(--color-font-label);
  text-align: center;
}
