/*自动隐藏文字*/
.container {
  position: absolute;
  display: flex;
  flex-flow: column nowrap;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  background-color: var(--color-content-background);
  z-index: 10;
  overflow: hidden;
  border-radius: 4px;
  color: var(--color-font);
  -webkit-app-region: no-drag;
  contain: strict;
  box-sizing: border-box;
}
.container * {
  box-sizing: border-box;
}
.bg {
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  background: var(--background-image) var(--background-image-position) no-repeat;
  background-size: var(--background-image-size);
  opacity: 0.7;
  z-index: -1;
}
.bg:before {
  content: '';
  display: block;
  width: 100%;
  height: 100%;
  background-color: var(--color-app-background);
}
.bg:after {
  position: absolute;
  left: 0;
  top: 0;
  content: '';
  display: block;
  width: 100%;
  height: 100%;
  background-color: var(--color-main-background);
}
.main {
  flex: auto;
  min-height: 0;
  overflow: hidden;
  display: flex;
  margin: 0 30px;
  position: relative;
}
.main.showComment :global .left {
  flex-basis: 18%;
}
.main.showComment :global .left .description p {
  font-size: 12px;
}
.main.showComment :global .right {
  flex-basis: 30%;
}
.main.showComment :global .right .lyricSelectContent {
  font-size: 14px;
}
.main.showComment :global .comment {
  opacity: 1;
  transform: scaleX(1);
}
.left {
  flex: 0 0 40%;
  display: flex;
  flex-flow: column nowrap;
  align-items: center;
  padding: 13px;
  overflow: hidden;
  transition: flex-basis 0.4s ease;
}
.info {
  display: flex;
  flex-flow: column nowrap;
  justify-content: flex-start;
  max-width: 300px;
  min-height: 0;
}
.img {
  max-width: 100%;
  max-height: 80%;
  min-width: 100%;
  box-shadow: 0 0 6px var(--color-primary-alpha-500);
  border-radius: 6px;
  opacity: 0.8;
}
.description {
  max-width: 300px;
  margin-top: 15px;
  padding-bottom: 15px;
  min-height: 0;
}
.description p {
  line-height: 1.5;
  font-size: 14px;
  overflow-wrap: break-word;
}
.comment {
  position: absolute;
  right: 0;
  top: 0;
  width: 50%;
  height: 100%;
  opacity: 1;
  margin-left: 10px;
  transform: scaleX(0);
}
