/*自动隐藏文字*/
.header {
  flex: none;
  padding: 15px;
  text-align: center;
}
.header h2 {
  word-break: break-all;
}
.main {
  min-height: 175px;
  min-width: 380px;
}
.list {
  min-height: 175px;
  min-width: 380px;
  font-size: 13px;
  transition-property: height;
}
.list .listItem {
  position: relative;
  padding: 0 5px;
  transition: background-color 0.2s ease;
  line-height: 1.4;
  height: 100%;
  display: flex;
  flex-flow: row nowrap;
  align-items: center;
}
.list .listItem:hover {
  background-color: var(--color-primary-background-hover);
}
.num {
  flex: none;
  font-size: 12px;
  width: 30px;
  text-align: center;
  color: var(--color-font-label);
}
.textContent {
  flex: auto;
  padding-left: 5px;
  min-width: 0;
  display: flex;
  flex-flow: column nowrap;
  align-items: flex-start;
  overflow: hidden;
}
.text {
  max-width: 100%;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.albumName {
  font-size: 12px;
  opacity: 0.6;
}
.label {
  flex: none;
  font-size: 12px;
  opacity: 0.5;
  padding: 0 5px;
  display: flex;
  align-items: center;
}
.btns {
  flex: none;
  font-size: 12px;
  padding: 0 5px;
  display: flex;
  align-items: center;
}
.btn {
  background-color: transparent;
  border: none;
  border-radius: 3px;
  margin-right: 5px;
  cursor: pointer;
  padding: 4px 7px;
  color: var(--color-button-font);
  outline: none;
  transition: background-color 0.2s ease;
  line-height: 0;
}
.btn:last-child {
  margin-right: 0;
}
.btn svg {
  height: 16px;
}
.btn:hover {
  background-color: var(--color-primary-background-hover);
}
.btn:active {
  background-color: var(--color-primary-font-active);
}
.noItem {
  position: relative;
  height: 200px;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  align-items: center;
}
.noItem p {
  font-size: 16px;
  color: var(--color-font-label);
}
