/*自动隐藏文字*/
.comment {
  display: flex;
  flex-flow: column nowrap;
  transition: 0.4s ease;
  transition-property: transform,opacity;
  transform-origin: 100%;
  overflow: hidden;
}
.commentHeader {
  flex: none;
  padding-bottom: 5px;
  display: flex;
  flex-flow: row nowrap;
  align-items: center;
}
.commentHeader h3 {
  font-size: 14px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  line-height: 1.2;
}
.commentHeaderBtns {
  flex: 1 0 auto;
  display: flex;
  flex-flow: row nowrap;
  justify-content: flex-end;
  color: var(--color-primary);
}
.commentHeaderBtn {
  height: 22px;
  width: 22px;
  cursor: pointer;
  transition: opacity 0.4s ease;
}
.commentHeaderBtn + .commentHeaderBtn {
  margin-left: 5px;
}
.commentHeaderBtn:hover {
  opacity: 0.7;
}
.commentMain {
  flex: auto;
  background-color: var(--color-primary-light-400-alpha-700);
  border-radius: 4px;
  display: flex;
  flex-direction: column;
}
.tab_header {
  display: flex;
  flex-flow: row nowrap;
  gap: 15px;
  padding-left: 15px;
  padding-right: 10px;
}
.tab_main {
  flex: auto;
  display: flex;
  flex-flow: row nowrap;
  overflow: hidden;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
}
.tab_content {
  flex-shrink: 0;
  width: 100%;
  position: relative;
}
.tab_content_scroll {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  padding-left: 15px;
  padding-right: 10px;
  scroll-behavior: smooth;
}
.commentLabel {
  padding: 15px;
  color: var(--color-font-label);
  font-size: 14px;
}
.commentType {
  padding: 5px;
  margin: 5px 0;
  font-size: 13px;
  background: none;
  border: none;
  cursor: pointer;
  transition: 0.4s ease;
  transition-property: opacity, color;
}
.commentType:hover {
  opacity: 0.7;
}
.commentType.active {
  color: var(--color-primary);
}
.commentFloor {
  opacity: 1;
  transition: opacity 0.4s ease;
}
.commentFloor.loading {
  opacity: 0.4;
}
.pagination {
  padding: 10px 0;
}
.unavailable {
  flex: auto;
  padding-top: 10%;
  text-align: center;
  font-size: 14px;
  color: var(--color-font-label);
}
