/*自动隐藏文字*/
.main {
  padding: 15px 8px 12px;
  min-width: 200px;
  min-height: 0;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
}
.main h2 {
  font-size: 16px;
  color: var(--color-font);
  line-height: 1.3;
  text-align: center;
}
.content {
  flex: auto;
  margin: 15px 0;
  padding: 0 7px;
}
.content h3 {
  font-weight: bold;
  line-height: 2;
}
.content p {
  line-height: 1.5;
  font-size: 14px;
  text-align: justify;
}
.btns {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.btn {
  display: block;
  width: 48%;
}
.btn:last-child {
  margin-bottom: 0;
}
