/*自动隐藏文字*/
.main {
  padding: 15px;
  max-width: 700px;
  min-width: 200px;
  min-height: 0;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
}
.main h2 {
  font-size: 16px;
  color: var(--color-font);
  line-height: 1.3;
  text-align: center;
}
.content {
  flex: auto;
  padding: 15px 0 5px;
  padding-right: 5px;
}
.content .btnGroup + .btnGroup {
  margin-top: 10px;
}
.content .label {
  color: var(--color-font-label);
  font-size: 14px;
  line-height: 2;
}
.content .desc {
  line-height: 1.5;
  font-size: 14px;
  text-align: justify;
}
.content .tipGroup {
  display: flex;
  flex-direction: row;
  font-size: 12px;
}
.content .tipGroup + .tipGroup {
  margin-top: 5px;
}
.content .tipGroup .title {
  white-space: nowrap;
  font-weight: bold;
  margin-right: 5px;
}
.content .tipGroup .tip {
  line-height: 1.3;
}
.btns {
  display: flex;
  align-items: center;
}
.btn {
  display: block;
  white-space: nowrap;
}
.btn + .btn {
  margin-left: 15px;
}
.btn:last-child {
  margin-bottom: 0;
}
