/*自动隐藏文字*/
.sliderContent {
  flex: none;
  position: relative;
  width: 100px;
  padding: 5px 0;
  display: flex;
  align-items: center;
  opacity: 0.5;
  transition: opacity 0.4s ease;
}
.sliderContent:hover {
  opacity: 1;
}
.sliderContent.disabled {
  opacity: 0.3;
}
.sliderContent.disabled .sliderMask {
  cursor: default;
}
.slider {
  width: 100%;
  height: 5px;
  border-radius: 20px;
  overflow: hidden;
  transition: 0.4s ease;
  transition-property: background-color, opacity;
  background-color: var(--color-primary-alpha-700);
  position: relative;
}
.sliderBar {
  position: absolute;
  left: 0;
  top: 0;
  transform: scaleX(0);
  transform-origin: 0;
  transition-property: transform;
  transition-timing-function: ease;
  width: 100%;
  height: 100%;
  transition-duration: 0.2s;
  background-color: var(--color-button-font);
  box-shadow: 0 0 2px rgba(0, 0, 0, 0.2);
}
.sliderMask {
  position: absolute;
  top: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
}
