/*自动隐藏文字*/
.main {
  padding: 10px 7px 0;
  width: 560px;
  max-width: 100%;
  box-sizing: border-box;
  display: flex;
  flex-flow: column nowrap;
  min-height: 0;
  height: 100%;
}
.tab {
  flex: none;
}
.list {
  flex: auto;
  min-height: 100px;
  min-width: 460px;
  font-size: 13px;
  transition-property: height;
  margin-top: 10px;
  padding: 0 7px;
}
.list .listItem {
  position: relative;
  padding: 10px 5px;
  transition: background-color 0.2s ease;
  line-height: 1.4;
  display: flex;
  flex-flow: row nowrap;
  align-items: center;
  border-radius: 4px;
}
.list .listItem:hover {
  background-color: var(--color-primary-background-hover);
}
.list .num {
  flex: none;
  font-size: 12px;
  width: 20px;
  text-align: center;
  color: var(--color-font-label);
}
.list .textContent {
  flex: auto;
  min-width: 0;
  display: flex;
  flex-flow: column nowrap;
  align-items: flex-start;
  overflow: hidden;
}
.list .text {
  max-width: 100%;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.list .albumName {
  font-size: 12px;
  opacity: 0.6;
}
.list .label {
  flex: none;
  font-size: 12px;
  opacity: 0.5;
  padding: 0 5px;
  display: flex;
  align-items: center;
}
.list .btns {
  flex: none;
  font-size: 12px;
  padding: 0 5px;
  display: flex;
  align-items: center;
}
.list .btn {
  background-color: transparent;
  border: none;
  border-radius: 3px;
  margin-right: 5px;
  cursor: pointer;
  padding: 4px 7px;
  color: var(--color-button-font);
  outline: none;
  transition: background-color 0.2s ease;
  line-height: 0;
}
.list .btn:last-child {
  margin-right: 0;
}
.list .btn svg {
  width: 16px;
  height: 16px;
}
.list .btn:hover {
  background-color: var(--color-primary-background-hover);
}
.list .btn:active {
  background-color: var(--color-primary-font-active);
}
.list .noItem {
  position: relative;
  display: flex;
  flex-flow: column nowrap;
  justify-content: center;
  align-items: center;
  height: 100%;
}
.list .noItem p {
  font-size: 16px;
  color: var(--color-font-label);
}
.footer {
  flex: none;
  display: flex;
  flex-flow: row nowrap;
  justify-content: space-between;
  align-items: center;
  padding: 10px 7px;
}
.footer .info {
  min-width: 0;
  display: flex;
  flex-flow: row nowrap;
  padding-right: 10px;
  gap: 10px;
  font-size: 12px;
  align-items: center;
}
.footer .info h2 {
  min-width: 0;
  color: var(--color-font);
  line-height: 1.5;
  word-break: break-all;
}
.footer .info .nameLabel {
  display: flex;
  flex-flow: row nowrap;
}
.footer .info .name {
  display: -webkit-box;
  overflow: hidden;
  text-overflow: ellipsis;
  word-wrap: break-word;
  word-break: break-all;
  white-space: normal !important;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
}
.footer .info .label {
  flex: none;
  font-size: 12px;
  opacity: 0.8;
  padding: 0 5px;
  color: var(--color-primary);
}
.footer .info .singer {
  color: var(--color-font-label);
  display: -webkit-box;
  overflow: hidden;
  text-overflow: ellipsis;
  word-wrap: break-word;
  word-break: break-all;
  white-space: normal !important;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
}
.footer .btn {
  flex: none;
  min-width: 70px;
}
.footer .btn + .btn {
  margin-left: 10px;
}
